- (void)saveManaged:(NSButton*)button key:(NSString*)key { [self.prefs setObject:button.state==NSControlStateValueOn?@"Ja":@"Nein" forKey:key]; }
- (void)save { if(self.selected)[self.prefs setObject:self.selected forKey:@"SelectedAddonsFolder"];[self.prefs setObject:self.languages.titleOfSelectedItem?:@"Deutsch" forKey:@"LanguagePack"];[self.prefs setObject:self.login.state==NSControlStateValueOn?@"Ja":@"Nein" forKey:@"LoginTool"];[self saveManaged:self.questie key:@"ManageQuestie"];[self saveManaged:self.atlas key:@"ManageAtlasLoot"];[self saveManaged:self.details key:@"ManageDetails"];[self saveManaged:self.pawn key:@"ManagePawn"];[self saveManaged:self.dbm key:@"ManageDBM"];[self saveManaged:self.gtfo key:@"ManageGTFO"];[self saveManaged:self.bugsack key:@"ManageBugSack"];[self.prefs synchronize]; }
- (void)updateManagedAvailability { BOOL anniversary=[self.selected containsString:@"/_anniversary_/"];for(NSButton*b in @[self.questie,self.atlas,self.details,self.dbm,self.gtfo,self.bugsack,self.pawn]){b.enabled=anniversary;b.accessibilityEnabled=anniversary;}NSString*help=anniversary?@"Die ausgewählten AddOns werden zusammen mit Sku aktualisiert.":@"Die zusätzliche AddOn-Verwaltung ist in dieser Ausbaustufe nur für Anniversary verfügbar.";for(NSButton*b in @[self.questie,self.atlas,self.details,self.dbm,self.gtfo,self.bugsack,self.pawn])b.accessibilityHelp=help; }
- (void)updatePath { self.path.stringValue=self.selected?:@"Noch kein AddOns-Ordner ausgewählt.";self.path.accessibilityLabel=self.path.stringValue;[self updateManagedAvailability]; }
- (NSString*)installed { NSString*t=[self.selected stringByAppendingPathComponent:@"Sku/Sku.toc"];NSString*x=t?[NSString stringWithContentsOfFile:t encoding:NSUTF8StringEncoding error:nil]:nil;NSRegularExpression*r=[NSRegularExpression regularExpressionWithPattern:@"(?im)^##\\s*Version:\\s*([^\\r\\n]+)" options:0 error:nil];NSTextCheckingResult*m=[r firstMatchInString:x?:@"" options:0 range:NSMakeRange(0,x.length)];return m?[[x substringWithRange:[m rangeAtIndex:1]]stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]:nil; }
- (NSDictionary*)addonManifest { NSString*p=[self.selected stringByAppendingPathComponent:@"SkuInstall.json"];NSData*d=p?[NSData dataWithContentsOfFile:p]:nil;if(!d)return @{};NSDictionary*j=[NSJSONSerialization JSONObjectWithData:d options:0 error:nil];NSDictionary*a=[j isKindOfClass:NSDictionary.class]?j[@"addons"]:nil;return[a isKindOfClass:NSDictionary.class]?a:@{}; }
- (BOOL)managedAddonCurrent:(NSDictionary*)manifest key:(NSString*)key version:(NSString*)version roots:(NSArray*)roots { if(![manifest[key] isEqualToString:version])return NO;for(NSString*r in roots)if(![[NSFileManager defaultManager]fileExistsAtPath:[self.selected stringByAppendingPathComponent:r]])return NO;return YES; }
- (NSString*)latestFor:(NSString*)key fallback:(NSString*)fallback { id entry=self.latestCurated[key];id value=[entry isKindOfClass:NSDictionary.class]?entry[@"latest"]:nil;return[value isKindOfClass:NSString.class]&&[value length]?value:fallback; }
- (void)applyLatestCuratedLabels { self.questie.title=[NSString stringWithFormat:@"Questie verwalten – verfügbar %@",[self latestFor:@"Questie" fallback:@"11.37.1"]];self.atlas.title=[NSString stringWithFormat:@"AtlasLootClassic Anniversary verwalten – verfügbar %@",[self latestFor:@"AtlasLoot" fallback:@"2.5.6.12334"]];self.details.title=[NSString stringWithFormat:@"Details Damage Meter verwalten – verfügbar %@",[self latestFor:@"Details" fallback:@"20260707.15250.172 TBC"]];self.dbm.title=[NSString stringWithFormat:@"Deadly Boss Mods verwalten – verfügbar %@",[self latestFor:@"DBM" fallback:@"12.1.8"]];self.gtfo.title=[NSString stringWithFormat:@"GTFO Gefahrenwarnung verwalten – verfügbar %@",[self latestFor:@"GTFO" fallback:@"6.9.1"]];self.bugsack.title=[NSString stringWithFormat:@"BugSack und BugGrabber verwalten – verfügbar %@",[self latestFor:@"BugSack" fallback:@"12.0.13"]];self.pawn.title=[NSString stringWithFormat:@"Pawn Ausrüstungsvergleich verwalten – verfügbar %@",[self latestFor:@"Pawn" fallback:@"2.13.15"]]; }
- (NSArray*)curatedUpdates { if(![self.selected containsString:@"/_anniversary_/"])return @[];NSDictionary*m=self.addonManifest;NSMutableArray*u=[NSMutableArray array];if(self.questie.state==NSControlStateValueOn&&![self managedAddonCurrent:m key:@"CurseQuestie" version:[self latestFor:@"Questie" fallback:@"11.37.1"] roots:@[@"Questie"]])[u addObject:@"Questie"];if(self.atlas.state==NSControlStateValueOn&&![self managedAddonCurrent:m key:@"CurseAtlasLootAnniversary" version:[self latestFor:@"AtlasLoot" fallback:@"2.5.6.12334"] roots:@[@"AtlasLootClassic",@"AtlasLootClassic_Data"]])[u addObject:@"AtlasLootClassic Anniversary"];if(self.details.state==NSControlStateValueOn&&![self managedAddonCurrent:m key:@"CurseDetailsTBC" version:[self latestFor:@"Details" fallback:@"20260707.15250.172_TBC"] roots:@[@"Details",@"Details_DataStorage"]])[u addObject:@"Details Damage Meter"];if(self.pawn.state==NSControlStateValueOn&&![self managedAddonCurrent:m key:@"CursePawnTBC" version:[self latestFor:@"Pawn" fallback:@"2.13.15"] roots:@[@"Pawn"]])[u addObject:@"Pawn"];if(self.dbm.state==NSControlStateValueOn&&![self managedAddonCurrent:m key:@"DBMCore" version:[self latestFor:@"DBM" fallback:@"12.1.8"] roots:@[@"DBM-Core",@"DBM-Raids-BC",@"DBM-Party-BC"]])[u addObject:@"Deadly Boss Mods"];if(self.gtfo.state==NSControlStateValueOn&&![self managedAddonCurrent:m key:@"CurseGTFO" version:[self latestFor:@"GTFO" fallback:@"6.9.1"] roots:@[@"GTFO"]])[u addObject:@"GTFO"];if(self.bugsack.state==NSControlStateValueOn&&(![self managedAddonCurrent:m key:@"BugSack" version:[self latestFor:@"BugSack" fallback:@"12.0.13"] roots:@[@"BugSack"]]||![self managedAddonCurrent:m key:@"CurseBugGrabber" version:@"12.0.21" roots:@[@"!BugGrabber"]]))[u addObject:@"BugSack und BugGrabber"];return u; }
- (NSString*)updateSummaryWithLatestSku:(NSString*)latest { NSMutableArray*u=[NSMutableArray array];NSString*have=self.installed;if(!have||![have isEqualToString:latest])[u addObject:@"Sku"];[u addObjectsFromArray:self.curatedUpdates];if(!u.count)return @"Alle AddOns sind auf dem neuesten Stand.";NSString*names=u.count==1?u.firstObject:[[u subarrayWithRange:NSMakeRange(0,u.count-1)]componentsJoinedByString:@", "];if(u.count>1)names=[NSString stringWithFormat:@"%@ und %@",names,u.lastObject];return u.count==1?[NSString stringWithFormat:@"Für %@ ist ein Update verfügbar.",names]:[NSString stringWithFormat:@"Für %@ sind Updates verfügbar.",names]; }
- (NSString*)spoken:(NSString*)v{return[v stringByReplacingOccurrencesOfString:@"." withString:@" Punkt "];}
- (void)setStatus:(NSString*)s announce:(BOOL)a { self.status.stringValue=s;self.status.accessibilityLabel=s;if(a)NSAccessibilityPostNotificationWithUserInfo(self.status,NSAccessibilityAnnouncementRequestedNotification,@{NSAccessibilityAnnouncementKey:s,NSAccessibilityPriorityKey:@(NSAccessibilityPriorityHigh)}); }
- (void)refreshCuratedWithLatestSku:(NSString*)latest announce:(BOOL)announce { NSTask*t=[NSTask new];t.executableURL=[NSURL fileURLWithPath:@"/bin/bash"];t.arguments=@[[NSBundle.mainBundle.resourcePath stringByAppendingPathComponent:@"SkuInstaller.command"],@"--addon-update-status"];NSPipe*p=[NSPipe pipe];t.standardOutput=p;t.standardError=[NSFileHandle fileHandleWithNullDevice];t.terminationHandler=^(NSTask*finished){NSData*d=[p.fileHandleForReading readDataToEndOfFile];NSDictionary*j=d?[NSJSONSerialization JSONObjectWithData:d options:0 error:nil]:nil;dispatch_async(dispatch_get_main_queue(),^{if([j isKindOfClass:NSDictionary.class])self.latestCurated=j;[self applyLatestCuratedLabels];[self setStatus:[self updateSummaryWithLatestSku:latest] announce:announce];[self reload:self.selected];});};if(![t launchAndReturnError:nil]){[self setStatus:[self updateSummaryWithLatestSku:latest] announce:announce];} }
/* Version detection resolves the releases/latest redirect and reads the tag —
   the same mechanism the Windows installer uses (GitHubClient.cs). Never scrape
   the website HTML for a version string. */
- (void)refreshStatus:(BOOL)announce { [self setStatus:@"Der Aktualisierungsstatus aller ausgewählten AddOns wird geprüft." announce:NO];NSMutableURLRequest*q=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:@"https://github.com/Sku75/Sku-WoW-Addon-TBC/releases/latest"]];q.HTTPMethod=@"HEAD";[[[NSURLSession sharedSession]dataTaskWithRequest:q completionHandler:^(NSData*d,NSURLResponse*r,NSError*e){NSString*tag=r.URL.lastPathComponent?:@"";if([tag hasPrefix:@"v"])tag=[tag substringFromIndex:1];NSRegularExpression*rx=[NSRegularExpression regularExpressionWithPattern:@"^[0-9]+(\\.[0-9]+)+$" options:0 error:nil];NSString*l=[rx firstMatchInString:tag options:0 range:NSMakeRange(0,tag.length)]?tag:@"43.3";dispatch_async(dispatch_get_main_queue(),^{[self refreshCuratedWithLatestSku:l announce:announce];});}]resume]; }
