- (NSString*)normalize:(NSString*)p { p=p.stringByStandardizingPath;if([p.lastPathComponent isEqualToString:@"AddOns"]&&[p.stringByDeletingLastPathComponent.lastPathComponent isEqualToString:@"Interface"])return p;if([p.lastPathComponent isEqualToString:@"Interface"])return[p stringByAppendingPathComponent:@"AddOns"];NSString*c=[p stringByAppendingPathComponent:@"Interface/AddOns"];return[[NSFileManager defaultManager]fileExistsAtPath:c]?c:nil; }
- (void)browse:(id)x { NSOpenPanel*p=NSOpenPanel.openPanel;p.title=@"AddOns-Ordner auswählen";p.message=@"Wähle den WoW-Versionsordner oder Interface/AddOns.";p.prompt=@"Auswählen";p.canChooseDirectories=YES;p.canChooseFiles=NO;if([p runModal]!=NSModalResponseOK)return;NSString*q=[self normalize:p.URL.path];if(!q){[self alert:@"Ungültiger Ordner" info:@"Bitte wähle einen WoW-Versionsordner oder Interface/AddOns."];return;}NSError*e;[[NSFileManager defaultManager]createDirectoryAtPath:q withIntermediateDirectories:YES attributes:nil error:&e];if(e){[self alert:@"Ordner nicht verwendbar" info:e.localizedDescription];return;}if(![self.paths containsObject:q])[self.paths addObject:q];[self reload:q];[self save];[self refreshStatus:YES]; }
- (void)busy:(BOOL)b { self.update.enabled=!b;self.repair.enabled=!b;self.inventory.enabled=!b;self.games.enabled=!b;self.languages.enabled=!b;self.login.enabled=!b;self.cancel.hidden=!b;self.progress.hidden=!b;if(b){for(NSButton*m in @[self.questie,self.atlas,self.details,self.dbm,self.gtfo,self.bugsack,self.pawn])m.enabled=NO;}else [self updateManagedAvailability];b?[self.progress startAnimation:nil]:[self.progress stopAnimation:nil]; }
- (void)backend:(NSString*)arg done:(void(^)(int,NSString*))done {
 [self save]; [self busy:YES]; self.output.stringValue=@"Vorgang wird gestartet …\n";
 self.task=[NSTask new]; self.task.executableURL=[NSURL fileURLWithPath:@"/bin/bash"];
 self.task.arguments=@[[NSBundle.mainBundle.resourcePath stringByAppendingPathComponent:@"SkuInstaller.command"],arg];
 self.pipe=[NSPipe pipe]; self.task.standardOutput=self.pipe; self.task.standardError=self.pipe;
 NSMutableData*all=[NSMutableData data]; __weak typeof(self) weakSelf=self;
 self.pipe.fileHandleForReading.readabilityHandler=^(NSFileHandle*h){
  NSData*d=h.availableData; if(!d.length)return; @synchronized(all){[all appendData:d];}
  NSString*s=[[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding];
  dispatch_async(dispatch_get_main_queue(),^{typeof(self) self=weakSelf;if(self&&s.length)self.output.stringValue=[self.output.stringValue stringByAppendingString:s];});
 };
 self.task.terminationHandler=^(NSTask*t){
  typeof(self) self=weakSelf;if(!self)return; self.pipe.fileHandleForReading.readabilityHandler=nil;
  NSString*s; @synchronized(all){s=[[NSString alloc]initWithData:all encoding:NSUTF8StringEncoding]?:@"";}
  dispatch_async(dispatch_get_main_queue(),^{typeof(self) self=weakSelf;if(!self)return;[self busy:NO];self.task=nil;done(t.terminationStatus,s);});
 };
 NSError*e;if(![self.task launchAndReturnError:&e]){[self busy:NO];self.task=nil;[self alert:@"Vorgang konnte nicht gestartet werden" info:e.localizedDescription];}
}
- (void)install:(BOOL)repair { if(!self.selected){[self browse:nil];if(!self.selected)return;}[self setStatus:repair?@"Vollständige Reparatur läuft. Bitte warten.":@"Sku und ausgewählte AddOns werden aktualisiert. Bitte warten." announce:YES];[self backend:repair?@"--headless-update-force":@"--headless-update" done:^(int c,NSString*s){[self alert:c==0?@"Aktualisierung abgeschlossen":@"Aktualisierung fehlgeschlagen" info:c==0?(repair?@"Sku und alle ausgewählten AddOns wurden vollständig neu installiert.":@"Sku und die ausgewählten Anniversary-AddOns wurden erfolgreich installiert oder aktualisiert."):@"Die vorherigen Versionen wurden bei einem Austauschfehler wiederhergestellt. Erstelle bei Bedarf ein Diagnosepaket."];[self refreshStatus:YES];}]; }
- (void)updateSku:(id)x{[self install:NO];}- (void)repairSku:(id)x{[self install:YES];}- (void)cancelTask:(id)x{if(self.task.running){[self.task interrupt];[self setStatus:@"Aktualisierung wird abgebrochen." announce:YES];}}
- (void)showInventory:(id)x{if(!self.selected){[self browse:nil];if(!self.selected)return;}[self setStatus:@"Die installierten AddOns werden erfasst." announce:YES];[self backend:@"--addon-inventory" done:^(int c,NSString*s){NSString*result=[s stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];self.output.stringValue=result.length?result:@"Es wurden keine AddOns erkannt.";self.output.accessibilityLabel=@"Installierte AddOns";[self setStatus:c==0?@"Die AddOn-Liste wurde erstellt.":@"Die AddOn-Liste konnte nicht erstellt werden." announce:YES];}];}
- (void)logs:(id)x{[self backend:@"--collect-logs" done:^(int c,NSString*s){[self alert:c==0?@"Diagnosepaket erstellt":@"Diagnose fehlgeschlagen" info:c==0?[NSString stringWithFormat:@"Die ZIP-Datei liegt hier:\n%@",[s stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]]:@"Das Paket konnte nicht erstellt werden."];}];}
- (void)checkApp:(id)x{[self backend:@"--self-update-check" done:^(int c,NSString*s){if(c!=0){[self alert:@"Prüfung fehlgeschlagen" info:@"Die Installer-Version konnte momentan nicht geprüft werden."];return;}if([s containsString:@"AVAILABLE=1"]){NSRegularExpression*r=[NSRegularExpression regularExpressionWithPattern:@"LATEST=([^\\r\\n]+)" options:0 error:nil];NSTextCheckingResult*m=[r firstMatchInString:s options:0 range:NSMakeRange(0,s.length)];NSString*v=m?[s substringWithRange:[m rangeAtIndex:1]]:@"neu";NSAlert*a=[NSAlert new];a.messageText=@"Neue Installer-Version verfügbar";a.informativeText=[NSString stringWithFormat:@"Version %@ kann aus dem offiziellen Repository geladen, per SHA-256 und Developer-ID-Signatur geprüft und installiert werden.",v];[a addButtonWithTitle:@"Jetzt aktualisieren"];[a addButtonWithTitle:@"Später"];if([a runModal]==NSAlertFirstButtonReturn){[self backend:@"--self-update" done:^(int code,NSString*out){if(code==0)[NSApp terminate:nil];else[self alert:@"Installer-Aktualisierung fehlgeschlagen" info:@"Das vorhandene Programm wurde nicht ersetzt. Das heruntergeladene Paket war nicht verfügbar oder bestand die Sicherheitsprüfung nicht."];}];}}else[self alert:@"Installer ist aktuell" info:@"Es ist keine neuere veröffentlichte macOS-Version verfügbar."];}];}
- (void)checkInstallerAutomatically { NSTask*t=[NSTask new];t.executableURL=[NSURL fileURLWithPath:@"/bin/bash"];t.arguments=@[[NSBundle.mainBundle.resourcePath stringByAppendingPathComponent:@"SkuInstaller.command"],@"--self-update-check"];NSPipe*p=[NSPipe pipe];t.standardOutput=p;t.standardError=[NSFileHandle fileHandleWithNullDevice];t.terminationHandler=^(NSTask*finished){NSData*d=[p.fileHandleForReading readDataToEndOfFile];NSString*s=[[NSString alloc]initWithData:d encoding:NSUTF8StringEncoding]?:@"";if([s containsString:@"AVAILABLE=1"])dispatch_async(dispatch_get_main_queue(),^{[self checkApp:nil];});};[t launchAndReturnError:nil]; }
- (void)alert:(NSString*)t info:(NSString*)i{NSAlert*a=[NSAlert new];a.messageText=t;a.informativeText=i;[a addButtonWithTitle:@"Schließen"];[a runModal];}
- (void)quit:(id)x{if(!self.task.running)[NSApp terminate:nil];}- (BOOL)windowShouldClose:(NSWindow*)w{if(self.task.running){[self alert:@"Aktualisierung läuft" info:@"Brich sie zuerst mit dem Schalter Aktualisierung abbrechen ab."];return NO;}return YES;}- (void)windowWillClose:(NSNotification*)n{[NSApp terminate:nil];}
@end
int main(int argc,const char*argv[]){@autoreleasepool{NSApplication*a=NSApplication.sharedApplication;SkuDelegate*d=[SkuDelegate new];a.delegate=d;[a run];}return 0;}
